import flask
from flask import request, jsonify, g
import psycopg2
import psycopg2.extras
import hashlib
import hmac
import os
import logging

app = flask.Flask(__name__)
logger = logging.getLogger(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS,
            cursor_factory=psycopg2.extras.RealDictCursor
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_api_key(key):
    """Verify API key against stored hash"""
    conn = get_db()
    cur = conn.cursor()
    key_hash = hashlib.sha256(key.encode()).hexdigest()
    cur.execute("SELECT client_id, permissions FROM api_keys WHERE key_hash = %s AND revoked = false", (key_hash,))
    return cur.fetchone()

@app.before_request
def authenticate():
    if request.endpoint == 'health':
        return
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'Missing API key'}), 401
    client = verify_api_key(api_key)
    if not client:
        return jsonify({'error': 'Invalid API key'}), 403
    g.client_id = client['client_id']
    g.permissions = client['permissions']

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria"""
    if 'read' not in g.permissions:
        return jsonify({'error': 'Insufficient permissions'}), 403

    search_field = request.args.get('field', 'username')
    search_value = request.args.get('q', '')
    sort_by = request.args.get('sort', 'created_at')
    sort_dir = request.args.get('dir', 'DESC')
    limit = request.args.get('limit', '50')

    # Validate sort direction
    if sort_dir.upper() not in ('ASC', 'DESC'):
        sort_dir = 'DESC'

    # Validate limit
    try:
        limit = min(int(limit), 200)
    except ValueError:
        limit = 50

    # Build query - field is validated against allowed list
    allowed_fields = ['username', 'email', 'display_name', 'department', 'role']
    if search_field not in allowed_fields:
        return jsonify({'error': f'Invalid search field. Allowed: {allowed_fields}'}), 400

    conn = get_db()
    cur = conn.cursor()

    # Construct the query with validated field but dynamic sort
    query = f"SELECT id, username, email, display_name, department, role, created_at FROM users WHERE {search_field} ILIKE %s ORDER BY {sort_by} {sort_dir} LIMIT {limit}"

    logger.info(f"Client {g.client_id} searching {search_field} for '{search_value}'")

    try:
        cur.execute(query, (f'%{search_value}%',))
        results = cur.fetchall()
        return jsonify({'results': results, 'count': len(results)})
    except psycopg2.Error as e:
        conn.rollback()
        logger.error(f"Query error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/v1/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    if 'read' not in g.permissions:
        return jsonify({'error': 'Insufficient permissions'}), 403
    conn = get_db()
    cur = conn.cursor()
    cur.execute("SELECT id, username, email, display_name, department, role, created_at FROM users WHERE id = %s", (user_id,))
    user = cur.fetchone()
    if not user:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(user)

@app.route('/api/v1/reports/export', methods=['POST'])
def export_report():
    """Export filtered user report"""
    if 'export' not in g.permissions:
        return jsonify({'error': 'Insufficient permissions'}), 403

    data = request.get_json()
    filters = data.get('filters', {})
    columns = data.get('columns', ['username', 'email', 'department'])

    # Validate columns
    valid_columns = ['id', 'username', 'email', 'display_name', 'department', 'role', 'created_at']
    columns = [c for c in columns if c in valid_columns]
    if not columns:
        columns = ['username', 'email']

    col_str = ', '.join(columns)
    where_clauses = []
    params = []

    if 'department' in filters:
        where_clauses.append("department = %s")
        params.append(filters['department'])
    if 'role' in filters:
        where_clauses.append("role = %s")
        params.append(filters['role'])

    where_sql = ' AND '.join(where_clauses) if where_clauses else '1=1'
    query = f"SELECT {col_str} FROM users WHERE {where_sql}"

    conn = get_db()
    cur = conn.cursor()
    cur.execute(query, params)
    results = cur.fetchall()
    return jsonify({'data': results, 'exported': len(results)})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
